PARAMS = ['Vmax','Km','Ki','alpha','Vinf']
def predict(df, p):
    S = df['S'].values; I = df['I'].values
    Vapp = p['Vmax']*(p['Vinf'] + (1-p['Vinf'])/(1+I/(p['alpha']*p['Ki'])) )
    Kapp = p['Km']*(1+I/p['Ki'])/(1+I/(p['alpha']*p['Ki']))
    return Vapp*S/(Kapp+S)

